import sys

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        n = int(next(iterator))
        q = int(next(iterator))
    except StopIteration:
        return

    MOD = 1000000007

    total_nodes = (1 << (n + 1)) - 1
    initial_edges = total_nodes - 1
    current_edges = initial_edges % MOD

    width = 1 << n
    height = n + 1
    horizontal_span = width - 1
    vertical_span = height - 1

    for _ in range(q):
        try:
            t = int(next(iterator))
        except StopIteration:
            break

        if t == 1:
            x = int(next(iterator))

            if x == 1:
                added = (width * horizontal_span) % MOD
                current_edges = (current_edges + added) % MOD
                horizontal_span = (horizontal_span * 2) % MOD

            elif x == 2:
                added = (width * horizontal_span) % MOD
                if added != 0:
                    current_edges = (current_edges + added) % MOD
                horizontal_span += 1
                if horizontal_span >= MOD:
                    horizontal_span %= MOD

            elif x == 3:
                added = (height * vertical_span) % MOD
                current_edges = (current_edges + added)
                if current_edges >= MOD:
                    current_edges %= MOD
                vertical_span = (vertical_span * 2) % MOD

            elif x == 4:
                added = (height * vertical_span) % MOD
                if added != 0:
                    current_edge_add = added
                    current_edges = (current_edges + current_edge_add)
                    if current_edges >= MOD:
                        current_edges %= MOD
                vertical_span += 1
                if vertical_span >= MOD:
                    vertical_span %= MOD

        else:
            print(current_edges)

if __name__ == "__main__":
    main()
